import{_ as l,a0 as o,w as r,s as d,ao as i,I as a,a1 as p,A as t,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"藉助 zope.interface 深入瞭解 Python 接口 | LCTT x X-CMD","titleTemplate":false,"description":"藉助 zope.interface 深入瞭解 Python 接口 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"藉助 zope.interface 深入瞭解 Python 接口 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"藉助 zope.interface 深入瞭解 Python 接口 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20190924 An advanced look at Python interfaces using zope.interface","title":"藉助 zope.interface 深入瞭解 Python 接口","tag":"202001","desc":""},"relativePath":"202001/20190924 An advanced look at Python interfaces using zope.interface.md","filePath":"[post].md"}'),f={name:"202001/20190924 An advanced look at Python interfaces using zope.interface.md"};function u(c,s,h,g,k,y){const e=o("Link");return r(),d("div",null,[s[20]||(s[20]=i('<h1 id="藉助-zope-interface-深入瞭解-python-接口" tabindex="-1">藉助 zope.interface 深入瞭解 Python 接口 <a class="header-anchor" href="#藉助-zope-interface-深入瞭解-python-接口" aria-label="Permalink to “藉助 zope.interface 深入瞭解 Python 接口”">​</a></h1><blockquote><p>Zope.interface 可以幫助聲明存在哪些接口，是由哪些對象提供的，以及如何查詢這些信息。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/getting_started_with_python.png?itok=MFEKm3gl" alt="Snake charmer cartoon with a yellow snake and a blue snake" title="Snake charmer cartoon with a yellow snake and a blue snake"></p><p><code>zope.interface</code> 庫可以克服 Python 接口設計中的歧義性。讓我們來研究一下。</p><h3 id="隱式接口不是-python-之禪" tabindex="-1">隱式接口不是 Python 之禪 <a class="header-anchor" href="#隱式接口不是-python-之禪" aria-label="Permalink to “隱式接口不是 Python 之禪”">​</a></h3>',5)),a("p",null,[p(e,{href:"https://en.wikipedia.org/wiki/Zen_of_Python"},{default:t(()=>[...s[0]||(s[0]=[n("Python 之禪",-1)])]),_:1}),s[1]||(s[1]=n(" 很寬鬆，但是有點自相矛盾，以至於你可以用它來例證任何東西。讓我們來思考其中最著名的原則之一：“顯示勝於隱式”。",-1))]),s[21]||(s[21]=a("p",null,[n("傳統上，在 Python 中會隱含的一件事是預期的接口。比如函數已經記錄了它期望一個“類文件對象”或“序列”。但是什麼是類文件對象呢？它支持 "),a("code",null,".writelines"),n("嗎？"),a("code",null,".seek"),n(" 呢？什麼是一個“序列”？是否支持步進切片，例如 "),a("code",null,"a[1:10:2]"),n("？")],-1)),s[22]||(s[22]=a("p",null,"最初，Python 的答案是所謂的“鴨子類型”，取自短語“如果它像鴨子一樣行走，像鴨子一樣嘎嘎叫，那麼它可能就是鴨子”。換句話説，“試試看”，這可能是你能得到的最具隱式的表達。",-1)),a("p",null,[s[3]||(s[3]=n("為了使這些內容顯式地表達出來，你需要一種方法來表達期望的接口。",-1)),p(e,{href:"http://zope.org"},{default:t(()=>[...s[2]||(s[2]=[n("Zope",-1)])]),_:1}),s[4]||(s[4]=n(" Web 框架是最早用 Python 編寫的大型系統之一，它迫切需要這些東西來使代碼明確呈現出來，例如，期望從“類似用户的對象”獲得什麼。",-1))]),s[23]||(s[23]=i(`<p><code>zope.interface</code> 由 Zope 開發，但作為單獨的 Python 包發佈。<code>Zope.interface</code> 可以幫助聲明存在哪些接口，是由哪些對象提供的，以及如何查詢這些信息。</p><p>想像編寫一個簡單的 2D 遊戲，它需要各種東西來支持精靈界面（LCTT 譯註：“<ruby>精靈<rt> Sprite</rt></ruby>”是指遊戲面板中各個組件）。例如，表示一個邊界框，但也要表示對象何時與一個框相交。與一些其他語言不同，在 Python 中，將屬性訪問作為公共接口一部分是一種常見的做法，而不是實現 getter 和 setter。邊界框應該是一個屬性，而不是一個方法。</p><p>呈現精靈列表的方法可能類似於：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def render_sprites(render_surface, sprites):</span></span>
<span class="line"><span>    &quot;&quot;&quot;</span></span>
<span class="line"><span>    sprites 應該是符合 Sprite 接口的對象列表：</span></span>
<span class="line"><span>    * 一個名為 &quot;bounding_box&quot; 的屬性，包含了邊界框</span></span>
<span class="line"><span>    * 一個名為 &quot;intersects&quot; 的方法，它接受一個邊界框並返回 True 或 False</span></span>
<span class="line"><span>    &quot;&quot;&quot;</span></span>
<span class="line"><span>    pass # 一些做實際渲染的代碼</span></span></code></pre></div><p>該遊戲將具有許多處理精靈的函數。在每個函數中，你都必須在隨附文檔中指定預期。</p><p>此外，某些函數可能期望使用更復雜的精靈對象，例如具有 Z 序的對象。我們必須跟蹤哪些方法需要 Sprite 對象，哪些方法需要 SpriteWithZ 對象。</p><p>如果能夠使精靈是顯式而直觀的，這樣方法就可以聲明“我需要一個精靈”，並有個嚴格定義的接口，這不是很好嗎？來看看 <code>zope.interface</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from zope import interface</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class ISprite(interface.Interface):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    bounding_box = interface.Attribute(</span></span>
<span class="line"><span>        &quot;邊界框&quot;</span></span>
<span class="line"><span>    )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    def intersects(box):</span></span>
<span class="line"><span>        &quot;它和一個框相交嗎？&quot;</span></span></code></pre></div><p>乍看起來，這段代碼有點奇怪。這些方法不包括 <code>self</code>，而包含 <code>self</code> 是一種常見的做法，並且它有一個<strong>屬性</strong>。這是在 <code>zope.interface</code> 中聲明接口的方法。這看起來很奇怪，因為大多數人不習慣嚴格聲明接口。</p><p>這樣做的原因是接口顯示瞭如何調用方法，而不是如何定義方法。因為接口不是超類，所以它們可以用來聲明數據屬性。</p><p>下面是一個能帶有圓形精靈的接口的一個實現：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@implementer(ISprite)</span></span>
<span class="line"><span>@attr.s(auto_attribs=True)</span></span>
<span class="line"><span>class CircleSprite:</span></span>
<span class="line"><span>    x: float</span></span>
<span class="line"><span>    y: float</span></span>
<span class="line"><span>    radius: float</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @property</span></span>
<span class="line"><span>    def bounding_box(self):</span></span>
<span class="line"><span>        return (</span></span>
<span class="line"><span>            self.x - self.radius,</span></span>
<span class="line"><span>            self.y - self.radius,</span></span>
<span class="line"><span>            self.x + self.radius,</span></span>
<span class="line"><span>            self.y + self.radius,</span></span>
<span class="line"><span>        )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    def intersects(self, box):</span></span>
<span class="line"><span>        # 當且僅當至少一個角在圓內時，方框與圓相交</span></span>
<span class="line"><span>        top_left, bottom_right = box[:2], box[2:]</span></span>
<span class="line"><span>        for choose_x_from (top_left, bottom_right):</span></span>
<span class="line"><span>            for choose_y_from (top_left, bottom_right):</span></span>
<span class="line"><span>                x = choose_x_from[0]</span></span>
<span class="line"><span>                y = choose_y_from[1]</span></span>
<span class="line"><span>                if (((x - self.x) \` 2 + (y - self.y) \` 2) &amp;lt;=</span></span>
<span class="line"><span>                    self.radius \` 2):</span></span>
<span class="line"><span>                     return True</span></span>
<span class="line"><span>        return False</span></span></code></pre></div><p>這<strong>顯式</strong>聲明瞭實現了該接口的 <code>CircleSprite</code> 類。它甚至能讓我們驗證該類是否正確實現了接口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from zope.interface import verify</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def test_implementation():</span></span>
<span class="line"><span>    sprite = CircleSprite(x=0, y=0, radius=1)</span></span>
<span class="line"><span>    verify.verifyObject(ISprite, sprite)</span></span></code></pre></div><p>這可以由 pytest、nose 或其他測試框架運行，它將驗證創建的精靈是否符合接口。測試通常是局部的：它不會測試僅在文檔中提及的內容，甚至不會測試方法是否可以在沒有異常的情況下被調用！但是，它會檢查是否存在正確的方法和屬性。這是對單元測試套件一個很好的補充，至少可以防止簡單的拼寫錯誤通過測試。</p><hr>`,16)),a("p",null,[s[6]||(s[6]=n("via: ",-1)),p(e,{href:"https://opensource.com/article/19/9/zopeinterface-python-package"},{default:t(()=>[...s[5]||(s[5]=[n("https://opensource.com/article/19/9/zopeinterface-python-package",-1)])]),_:1})]),a("p",null,[s[11]||(s[11]=n("作者：",-1)),p(e,{href:"https://opensource.com/users/moshez"},{default:t(()=>[...s[7]||(s[7]=[n("Moshe Zadka",-1)])]),_:1}),s[12]||(s[12]=n(" 選題：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[n("lujun9972",-1)])]),_:1}),s[13]||(s[13]=n(" 譯者：",-1)),p(e,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[9]||(s[9]=[n("MjSeven",-1)])]),_:1}),s[14]||(s[14]=n(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[n("Linux中國",-1)])]),_:1}),s[19]||(s[19]=n(" 榮譽推出",-1))])])}const T=l(f,[["render",u]]);export{x as __pageData,T as default};
